import {repairExamEvidence} from './workshop-repair-exam-model.mjs';
import {repairWeekly} from './workshop-repair-weekly.mjs';
import {readRepairGoal,repairDay} from './workshop-repair-review.mjs';
export function mountRepairWeekly({language,host,faultName,launch,available}){
 const root=document.createElement('section');root.id='repairWeekly';root.className='challenge-panel';host.before(root);let lastRows=[];
 const t=(es,en)=>language()==='es'?es:en,date=day=>new Date(day+'T12:00:00Z').toLocaleDateString(language(),{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'});
 function render(rows=lastRows){lastRows=rows;let goal=2,goalError=false;try{goal=readRepairGoal(localStorage);}catch{goalError=true;}const s=(()=>{let evidence=[];try{evidence=repairExamEvidence(localStorage);}catch{}return repairWeekly(rows,goal,new Date(),evidence);})();root.replaceChildren();const add=(tag,text,parent=root)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};const practice=(entry,parent)=>{const b=add('button',t('Practicar en 3D','Practise in 3D'),parent);b.dataset.weeklyRepair=entry.key;b.disabled=!available();b.onclick=()=>launch(entry);};
 add('h2',t('Tu semana de reparaciones','Your repair week'));const examLink=add('a',t('Iniciar examen semanal de reparación','Start weekly repair exam'));examLink.href='workshop-repair-exam.html?lang='+language();add('p',date(s.start)+' – '+date(s.today)+' · Bogotá');
 const metrics=add('div','');metrics.className='repair-weekly-metrics';for(const [label,value]of [[t('Reparaciones verificadas','Verified repairs'),s.current.count],[t('Nota media','Average score'),s.current.average===null?'—':s.current.average+'/100'],[t('Días de práctica','Practice days'),s.current.days],[t('Racha actual','Current streak'),s.streak]]){const card=add('article','',metrics);add('strong',String(value),card);add('p',label,card);}
 add('p',t('Comparación con ','Compared with ')+date(s.priorStart)+' – '+date(s.priorEnd)+': '+(s.delta===null?t('faltan resultados en uno de los períodos.','one period has no results yet.'):(s.delta>0?'+':'')+s.delta+t(' puntos de nota media.',' average-score points.')));add('p',t('Semana anterior, mismos días: ','Previous week, same weekdays: ')+s.previous.count+t(' reparaciones · media ',' repairs · average ')+(s.previous.average===null?'—':s.previous.average+'/100'));
 add('p',s.current.hints+t(' pistas · ',' hints · ')+s.current.unnecessary+t(' intervenciones innecesarias · ',' unnecessary interventions · ')+s.current.failedChecks+t(' verificaciones fallidas esta semana.',' failed verifications this week.'));
 add('h3',t('Averías que más te cuestan esta semana','Hardest faults this week'));if(!s.hardest.length)add('p',s.current.count?t('Sin penalizaciones registradas esta semana. Sigue repasando para consolidar lo aprendido.','No recorded penalties this week. Keep reviewing to reinforce what you learned.'):t('Completa una reparación para empezar tu resumen.','Complete a repair to start your summary.'));
 for(const g of s.hardest){const card=add('article','');card.className='repair-progress-card';add('h4',faultName(g),card);add('p',t('Media reciente de la semana: ','Recent average this week: ')+g.mean+'/100 · '+g.hints+t(' pistas · ',' hints · ')+g.unnecessary+t(' intervenciones innecesarias · ',' unnecessary interventions · ')+g.failedChecks+t(' verificaciones fallidas',' failed verifications'),card);practice(g,card);}
 add('h3',t('Plan para la próxima semana','Next week’s review plan'));add('p',date(s.plan.start)+' – '+date(s.plan.end));add('p',t('Hasta ','Up to ')+s.plan.capacity+t(' retos por día, según tu meta diaria. Primero las averías con menor nota reciente que ya deban repasarse. Cada avería aparece una sola vez; las siguientes fechas se recalculan cuando practicas. Puedes adelantar un reto.',' challenges per day, based on your daily goal. Lower-scoring faults are prioritized once due. Each fault appears once; later dates are recalculated when you practise. You can practise a challenge early.'));
 if(goalError)add('p',t('No se pudo leer la meta; se usa 2 para este plan.','Could not read the goal; this plan uses 2.'));
 const plan=add('div','');plan.className='repair-weekly-plan';for(const day of s.plan.days){const card=add('article','',plan);add('h4',date(day.day),card);if(!day.entries.length)add('p',t('Sin retos previstos. Se actualizará al practicar.','No challenges planned. Updates with practice.'),card);for(const entry of day.entries){add('p',faultName(entry)+' · '+t('Media reciente ','Recent average ')+entry.mean+'/100 · '+t('Vencimiento original: ','Original due date: ')+date(entry.due),card);practice(entry,card);}}
 add('p',s.plan.scheduled+t(' retos previstos · ',' planned challenges · ')+s.plan.backlog+t(' pendientes sin espacio esta semana.',' due reviews beyond this week’s capacity.'));
 add('p',t('Resumen basado en las últimas 100 reparaciones. El plan también prioriza errores de exámenes de reparación, sin darles crédito de actividad. La comparación de medias puede cambiar si practicas averías diferentes; no es una prueba de dominio. El plan es provisional y no supone que ya hayas completado los retos futuros.','Summary uses the latest 100 repairs. The plan also prioritizes repair-exam mistakes without activity credit. Average scores can change when you practise different faults; this is not proof of mastery. The plan is provisional and does not assume future challenges are completed.'));if(!available())add('p',t('Abre un examen completado para acceder a los bancos de reparación.','Open a completed exam to access the repair benches.'));
 }
 let day=repairDay();setInterval(()=>{if(day!==repairDay()){day=repairDay();render();}},60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});return {render};
}
